#!/usr/bin/env node
/**
 * Inlines the pdf.js library and worker into a TypeScript module so the
 * renderer WebView works offline, without loading scripts from a CDN.
 * Runs automatically on `npm install` (postinstall).
 */

const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const buildDir = path.join(root, 'node_modules', 'pdfjs-dist', 'build');
const outFile = path.join(root, 'src', 'lib', 'pdf-renderer', 'pdfjs-source.generated.ts');

function read(name) {
  // Escape closing script tags so the source can be embedded in an inline <script>.
  return fs.readFileSync(path.join(buildDir, name), 'utf8').replace(/<\/script/gi, '<\\/script');
}

const contents = `// AUTO-GENERATED by scripts/bundle-pdfjs.js. Do not edit.
export const PDFJS_LIB = ${JSON.stringify(read('pdf.min.js'))};
export const PDFJS_WORKER = ${JSON.stringify(read('pdf.worker.min.js'))};
`;

fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, contents);
console.log(`pdf.js bundled into ${path.relative(root, outFile)}`);
